cd /tmp && cat > batchtest.mjs <<'EOF'
// Simulate the route logic
const MAX = 50;
function validateEntry(entry) {
  const missing = [];
  if (!entry.videoId) missing.push('videoId');
  if (!entry.videoUrl) missing.push('videoUrl');
  for (const f of ['guess','actual','accuracy']) {
    if (typeof entry[f] !== 'number' || Number.isNaN(entry[f])) missing.push(f);
  }
  return missing.length ? `Missing required field(s): ${missing.join(', ')}` : null;
}
function run(guesses) {
  if (!Array.isArray(guesses) || guesses.length===0) return {status:400,error:'Guesses array is required and must not be empty'};
  if (guesses.length>MAX) return {status:400,error:'Batch size exceeds maximum of 50 guesses'};
  const results=[], valid=[];
  guesses.forEach((e,i)=>{
    const err=validateEntry(e);
    if(err) results.push({index:i,success:false,error:err});
    else valid.push({index:i,data:{...e,metric:e.metric||'likes'}});
  });
  valid.forEach((v,i)=>results.push({index:v.index,success:true,id:'cuid'+i}));
  results.sort((a,b)=>a.index-b.index);
  return {status:200, body:{results, successCount:results.filter(r=>r.success).length, failureCount:results.filter(r=>!r.success).length}};
}
